import ast
from typing import Any

import griffe


class AppendCheckedExtension(griffe.Extension):
    """Griffe extension that appends ' [checked]' to every collected function's docstring."""

    def on_function_instance(
        self,
        *,
        node: ast.AsyncFunctionDef | ast.FunctionDef | griffe.ObjectNode,
        func: griffe.Function,
        agent: griffe.Visitor | griffe.Inspector,
        **kwargs: Any,
    ) -> None:
        if func.docstring is not None:
            func.docstring.value += " [checked]"


extensions = griffe.load_extensions(AppendCheckedExtension())

